a=[list(map(int,l.split())) for l in I.splitlines()];b=[list(map(int,l.split())) for l in O.splitlines()];R,C=len(a),len(a[0]);seed={(3,3),(3,4),(4,5)};converted={(r,c) for r in range(R) for c in range(C) if a[r][c]==0 and b[r][c]==8}
for mode in ('8flood','clear-line','diagonal','near-seed'):
 if mode=='8flood':
  vis=set(seed);q=deque(seed)
  while q:
   r,c=q.popleft()
   for dr in (-1,0,1):
    for dc in (-1,0,1):
     p=(r+dr,c+dc)
     if (dr or dc) and 0<=p[0]<R and 0<=p[1]<C and a[p[0]][p[1]]==0 and p not in vis:vis.add(p);q.append(p)
 elif mode=='clear-line':
  vis=set()
  for r in range(R):
   for c in range(C):
    if a[r][c]==0 and any((r-sr)==(c-sc) or (r-sr)==-(c-sc) for sr,sc in seed):
     # intervening cells are only zeros or seeds
     ok=True
     # line via unit step
     sr,sc=next(((sr,sc) for sr,sc in seed if (r-sr)==(c-sc) or (r-sr)==-(c-sc)),(r,c))
     dr=(r>sr)-(r<sr);dc=(c>sc)-(c<sc);x,y=sr+dr,sc+dc
     while (x,y)!=(r,c):
      if a[x][y]!=0:ok=False
      x+=dr;y+=dc
     if ok:vis.add((r,c))
 elif mode=='diagonal':
  vis=set(seed)
  for _ in range(100):
   old=len(vis)
   vis|={(r,c) for r in range(R) for c in range(C) if a[r][c]==0 and any((r+dr,c+dc) in vis for dr in (-1,1) for dc in (-1,1))}
   if len(vis)==old:break
 else: vis={(r,c) for r in range(R) for c in range(C) if a[r][c]==0 and any(max(abs(r-sr),abs(c-sc))<=2 for sr,sc in seed)}
 conv={p for p in vis if a[p[0]][p[1]]==0}
 print(mode,len(conv),len(conv&converted),len(conv-converted),len(converted-conv))

